from fastapi import APIRouter, HTTPException

from ledgerly.db import get_session
from ledgerly.invoices.models import Invoice
from ledgerly.invoices.schemas import InvoiceOut

router = APIRouter(prefix="/invoices", tags=["invoices"])


@router.get("/{invoice_id}", response_model=InvoiceOut)
def get_invoice(invoice_id: int):
    """Return one invoice with its lines and total."""
    with get_session() as s:
        inv = s.get(Invoice, invoice_id)
        if inv is None:
            raise HTTPException(404, "invoice not found")
        return InvoiceOut.model_validate(inv, from_attributes=True)

